test/refund.test.ts:
import {expect, test} from 'bun:test';
import {OrdersDb} from '../src/db';
import {refundOrder} from '../src/factory';
import {OrderTagRepo} from '../src/order-tag-repo';
import {RefundRepo} from '../src/refund-repo';

test('refund repository uses the injected client and records the order', () => {
  const client = new OrdersDb('synthetic://db');
  const repo = new RefundRepo(client);
  repo.save('refund-1', 'order-1');
  expect(repo.client).toBe(client);
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund:refund-1:order-1');
});

test('refundOrder uses the supplied shared client', () => {
  const client = new OrdersDb('synthetic://db');
  refundOrder(client, 'refund-1', 'order-1');
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund:refund-1:order-1');
});

test('order tags use a scalar link id and preserve the natural pair', () => {
  const client = new OrdersDb('synthetic://db');
  const repo = new OrderTagRepo(client);
  repo.add('order-1', 'priority');
  expect(repo.client).toBe(client);
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('order_tag:order-1:priority');
});
